#!/usr/bin/env bash
# M10 T00: idle-CPU baseline with the window minimized for five minutes.
#
# Everything runs against temp APPDATA / LOCALAPPDATA / USERPROFILE / HOME and
# a temp typical vault generated by cmd/genvault, so no real app data, real
# knowledge base or real tool directory is read or written. The real app-data
# folder is fingerprinted before and after as a guard.
#
# Usage (repo root):  bash spikes/m10-effects/cpu/run-cpu.sh
#   APP=/path/to/app.exe  SECONDS_TO_MEASURE=300  SETTLE_SECONDS=60
set -u
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../../.." && pwd)"
APP="${APP:-$ROOT/build/windows-amd64/Mile Knowledge Base.exe}"
MEASURE="${SECONDS_TO_MEASURE:-300}"
SETTLE="${SETTLE_SECONDS:-60}"
WORK=$(mktemp -d "$HERE/.cpu-XXXXXX")
VAULT="$WORK/vault"; APPD="$WORK/appdata"; LOCAL="$WORK/localappdata"; HOMEDIR="$WORK/home"
mkdir -p "$VAULT" "$APPD/Mile Knowledge Base" "$LOCAL" "$HOMEDIR"
# PowerShell 7 is the project default; this host only has Windows PowerShell
# 5.1, which is fine for this ASCII-only script.
PS="$(command -v pwsh.exe || command -v powershell.exe)"

cleanup() {
  "$PS" -NoProfile -Command 'Get-Process "Mile Knowledge Base" -ErrorAction SilentlyContinue | Where-Object { $_.Path -like "*m10-effects*" } | Stop-Process -Force' >/dev/null 2>&1
  rm -rf "$WORK"
}
trap cleanup EXIT

(cd "$ROOT" && go run ./cmd/genvault -kind typical -out "$(cygpath -w "$VAULT")" >/dev/null) || exit 1

python -I - "$VAULT" "$APPD/Mile Knowledge Base" "$HOMEDIR" <<'PY'
import hashlib, json, os, sys
v, out, home = sys.argv[1], sys.argv[2], sys.argv[3]
root = os.path.abspath(v)
vid = hashlib.sha256(root.replace('/', chr(92)).lower().encode()).hexdigest()[:16]
doc = {
    "version": 1,
    "theme": "light",
    "closeBehavior": "quit",
    "layout": {"sidebarWidth": 232, "docWidth": 560, "docCollapsed": True, "sidebarCollapsed": False,
               "agnesControlsCollapsed": False, "agnesHistoryOpen": True, "agnesComposerHeight": 96},
    "recentVaults": [{"id": vid, "root": root, "displayName": "m10-cpu", "lastOpenedAt": "2026-11-27T09:00:00Z"}],
    "lastVaultId": vid,
}
open(os.path.join(out, "settings.json"), "w", encoding="utf-8").write(json.dumps(doc, ensure_ascii=False, indent=2) + "\n")
print(vid)
PY

REAL="$(cygpath -u "${APPDATA:-}")/Mile Knowledge Base"
snapshot() {
  if [ -d "$REAL" ]; then
    (cd "$REAL" && find . -type f -printf '%P %s %T@\n' 2>/dev/null | sort)
  else
    echo "absent"
  fi
}
snapshot > "$WORK/real-before.txt"

OUT="${OUT:-$HERE/cpu-baseline.json}"
APPDATA="$(cygpath -w "$APPD")" \
LOCALAPPDATA="$(cygpath -w "$LOCAL")" \
USERPROFILE="$(cygpath -w "$HOMEDIR")" \
HOME="$(cygpath -w "$HOMEDIR")" \
"$PS" -NoProfile -ExecutionPolicy Bypass -File "$(cygpath -w "$HERE/cpu-baseline.ps1")" \
  -AppPath "$(cygpath -w "$APP")" -AppData "$(cygpath -w "$APPD")" \
  -Seconds "$MEASURE" -SettleSeconds "$SETTLE" | tee "$OUT"
STATUS=${PIPESTATUS[0]}

snapshot > "$WORK/real-after.txt"
if cmp -s "$WORK/real-before.txt" "$WORK/real-after.txt"; then
  echo "REAL_APPDATA_UNCHANGED=yes"
else
  echo "REAL_APPDATA_UNCHANGED=no"
  diff "$WORK/real-before.txt" "$WORK/real-after.txt" | head -20
fi
echo "APP_BUILD=$APP"
exit $STATUS
